import codecs
for mode in ('encode', 'decode', 'translate'):
    for data in ('', 'a', 'é', chr(0xd800), chr(0xdc80), '😀', 'ab'):
        for start in (-20, -1, 0, 1, 2, 20):
            for end in (-20, -1, 0, 1, 2, 20):
                if mode == 'encode':
                    e = UnicodeEncodeError('utf-8', data, start, end, 'probe')
                elif mode == 'decode':
                    e = UnicodeDecodeError('utf-8', data.encode('utf-8', 'surrogatepass'), start, end, 'probe')
                else:
                    e = UnicodeTranslateError(data, start, end, 'probe')
                for name in ('ignore', 'replace', 'backslashreplace', 'xmlcharrefreplace', 'namereplace', 'surrogateescape', 'surrogatepass'):
                    try:
                        r = codecs.lookup_error(name)(e)
                        print(mode, repr(data), start, end, name, 'ok', repr(r))
                    except Exception as error:
                        print(mode, repr(data), start, end, name, type(error).__name__, repr(error.args))
